const getConsentGateClaimedRows = `-- name: GetConsentGateClaimedRows :many
SELECT q.id,
       q.recipient_email,
       q.recipient_sub,
       q.priority,
       q.created_at,
       t.key,
       coalesce(t.system, false)::boolean AS system,
       mt.purpose,
       mt.category,
       (mt.purpose IS NOT DISTINCT FROM 'duyuru' AND mt.commercial_content_absent IS FALSE)::boolean AS promotional,
       (ml.id IS NOT NULL)::boolean AS to_list,
       (mt.own_event_statement IS TRUE AND mt.mail_list_id IS NOT NULL)::boolean AS own_event,
       mt.self_test
FROM mail_queue q
         JOIN mail_tasks mt ON mt.id = q.task_id
         LEFT JOIN templates t ON t.id = mt.template_id
         LEFT JOIN mailing_lists ml ON ml.id = mt.mail_list_id
WHERE q.id = ANY ($1::uuid[])
  AND q.channel = 'email'
  AND q.status = 'processing'
  AND q.claimed_by = $2::text
  AND (mt.purpose IS NOT DISTINCT FROM 'duyuru' OR ml.id IS NOT NULL)
`

type GetConsentGateClaimedRowsParams struct {
	Ids       []uuid.UUID `json:"ids"`
	ClaimedBy string      `json:"claimed_by"`
}

type GetConsentGateClaimedRowsRow struct {
	ID             uuid.UUID  `json:"id"`
	RecipientEmail string     `json:"recipient_email"`
	RecipientSub   *uuid.UUID `json:"recipient_sub"`
	Priority       int16      `json:"priority"`
	CreatedAt      *time.Time `json:"created_at"`
	Key            *string    `json:"key"`
	System         bool       `json:"system"`
	Purpose        *string    `json:"purpose"`
	Category       *string    `json:"category"`
	Promotional    bool       `json:"promotional"`
	ToList         bool       `json:"to_list"`
	OwnEvent       bool       `json:"own_event"`
	SelfTest       bool       `json:"self_test"`
}

// The claimed e-mail rows among ids whose send a contact consent may hold
// back (internal/mailer/consent_gate.go): a duyuru send (a promotional one,
// commercial_content_absent false, and any other to an address without an
// account), or a send to an internal list (one queued before purposes too).
// With the send's template (account mail is never held), purpose, category,
// whether it is a test mail to its own sender, the own event statement (only
// a list's or a Keycloak group's send, mail_list_id, may make it), and the
// recipient's account, when the row knows it. A send without a purpose that
// goes to no list (queued before purposes) is not read.
func (q *Queries) GetConsentGateClaimedRows(ctx context.Context, arg GetConsentGateClaimedRowsParams) ([]GetConsentGateClaimedRowsRow, error) {
	rows, err := q.db.Query(ctx, getConsentGateClaimedRows, arg.Ids, arg.ClaimedBy)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetConsentGateClaimedRowsRow
	for rows.Next() {
		var i GetConsentGateClaimedRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.RecipientEmail,
			&i.RecipientSub,
			&i.Priority,
			&i.CreatedAt,
			&i.Key,
			&i.System,
			&i.Purpose,
			&i.Category,
			&i.Promotional,
			&i.ToList,
			&i.OwnEvent,
			&i.SelfTest,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const getDailySentCounts = `-- name: GetDailySentCounts :many
WITH today AS (SELECT ($2::timestamptz AT TIME ZONE $1::text)::date AS day),
     days AS (SELECT today.day - back AS day
              FROM today,
                   generate_series(0, $3::int - 1) AS back)
SELECT d.day::date        AS day,
       count(q.created_at) AS sent
FROM days d
         LEFT JOIN mail_queue q
                   ON q.status = 'sent'
                       AND q.created_at >= (d.day::timestamp AT TIME ZONE $1::text)
                       AND q.created_at < ((d.day + 1)::timestamp AT TIME ZONE $1::text)
GROUP BY d.day
ORDER BY d.day
`

type GetDailySentCountsParams struct {
	TimeZone string    `json:"time_zone"`
	AsOf     time.Time `json:"as_of"`
	Days     int       `json:"days"`
}

type GetDailySentCountsRow struct {
	Day  time.Time `json:"day"`
	Sent int64     `json:"sent"`
}

// A queue row has no sent time of its own. created_at — when that recipient's
// mail was queued — stands in for it: the dispatcher is woken on enqueue, so a
// mail that goes through on its first attempt leaves within seconds, and only a
// retried one (the ladder tops out under eight minutes) can land later.
// next_attempt_at is not used: every row older than the retry migration holds
// that migration's timestamp in it.
// Days are calendar days in time_zone; the series ends on as_of's day and has
// one row per day, zero-filled.
func (q *Queries) GetDailySentCounts(ctx context.Context, arg GetDailySentCountsParams) ([]GetDailySentCountsRow, error) {
	rows, err := q.db.Query(ctx, getDailySentCounts, arg.TimeZone, arg.AsOf, arg.Days)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetDailySentCountsRow
	for rows.Next() {
		var i GetDailySentCountsRow
		if err := rows.Scan(&i.Day, &i.Sent); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

