type UpsertNotificationVariantParams struct {
	Type    string `json:"type"`
	Channel string `json:"channel"`
	Title   string `json:"title"`
	Summary string `json:"summary"`
	Link    string `json:"link"`
}

// A notification type's text on a channel other than e-mail (hub ticket
// iletisim-servisi 05: inbox), as the Template seed states it with the type.
func (q *Queries) UpsertNotificationVariant(ctx context.Context, arg UpsertNotificationVariantParams) (NotificationVariant, error) {
	row := q.db.QueryRow(ctx, upsertNotificationVariant,
		arg.Type,
		arg.Channel,
		arg.Title,
		arg.Summary,
		arg.Link,
	)
	var i NotificationVariant
	err := row.Scan(
		&i.Type,
		&i.Channel,
		&i.Title,
		&i.Summary,
		&i.Link,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertTemplateByKey = `-- name: UpsertTemplateByKey :one
INSERT INTO templates (key, name, subject, html_content, plain_text_content, react_email_content, system,
                       contract_required_variables, content_sensitive, sensitive_variables)
VALUES ($1::text,
        $2::text,
        $3::text,
        $4::text,
        $5::text,
        $6::text,
        $7::boolean,
        COALESCE($8::jsonb, '[]'),
        $9::boolean,
        $10::text[])
ON CONFLICT (key) DO UPDATE
    SET name                = EXCLUDED.name,
        subject             = EXCLUDED.subject,
        html_content        = EXCLUDED.html_content,
        plain_text_content  = EXCLUDED.plain_text_content,
        react_email_content = EXCLUDED.react_email_content,
        system              = EXCLUDED.system,
        -- Whether a send's content is shown is the seed's too: a seed that
        -- says (true or false) sets it, a seed that does not (NULL) leaves it.
        content_sensitive   = COALESCE($9::boolean, templates.content_sensitive),
        -- So are the variables a send's masking hides whole: a seed that
        -- sends a list (sorted, each name once, by the caller; [] clears it)
        -- replaces it, a seed that sends none (NULL) leaves it.
        sensitive_variables = COALESCE($10::text[], templates.sensitive_variables),
        -- The contract set is the seed's, like the key: a seed that sends one
        -- replaces it (sorted, each name once, by the caller), a seed that
        -- sends none (NULL) leaves it. A name the contract now declares leaves
        -- the operators' set, so the two never share one and it shows as
        -- locked.
        contract_required_variables = COALESCE($8::jsonb,
                                               templates.contract_required_variables),
        operator_required_variables = ARRAY(SELECT name
                                            FROM unnest(templates.operator_required_variables) AS name
                                            WHERE name <> ALL (contract_variable_names(
                                                    COALESCE($8::jsonb,
                                                             templates.contract_required_variables)))
                                            ORDER BY name COLLATE "C"),
        archived_at         = NULL,
        archived_by         = NULL,
        -- A seed that goes through settles any seed refused before it.
        seed_refused_at             = NULL,
        seed_refused_rules          = NULL,
        seed_refused_payload_sha256 = NULL,
        updated_at          = NOW()
RETURNING id, name, html_content, plain_text_content, react_email_content, created_at, updated_at, subject, archived_at, archived_by, key, system, published_version_id, contract_required_variables, operator_required_variables, seed_refused_at, seed_refused_rules, seed_refused_payload_sha256, content_sensitive, sensitive_variables, channel
`

type UpsertTemplateByKeyParams struct {
	Key                       string   `json:"key"`
	Name                      string   `json:"name"`
	Subject                   string   `json:"subject"`
	HtmlContent               string   `json:"html_content"`
	PlainTextContent          string   `json:"plain_text_content"`
	ReactEmailContent         string   `json:"react_email_content"`
	System                    bool     `json:"system"`
	ContractRequiredVariables []byte   `json:"contract_required_variables"`
	ContentSensitive          *bool    `json:"content_sensitive"`
	SensitiveVariables        []string `json:"sensitive_variables"`
}

// The seed writes everything it sends, the subject included. It is the
// caller that keeps an operator's change — the subject too — from being
// overwritten: it refuses the seed before it gets here unless it is forced
// (ADR-0047), which is what replaced leaving the subject alone on every seed.
func (q *Queries) UpsertTemplateByKey(ctx context.Context, arg UpsertTemplateByKeyParams) (Template, error) {
	row := q.db.QueryRow(ctx, upsertTemplateByKey,
		arg.Key,
		arg.Name,
		arg.Subject,
		arg.HtmlContent,
		arg.PlainTextContent,
		arg.ReactEmailContent,
		arg.System,
		arg.ContractRequiredVariables,
		arg.ContentSensitive,
		arg.SensitiveVariables,
	)
	var i Template
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.HtmlContent,
		&i.PlainTextContent,
		&i.ReactEmailContent,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Subject,
		&i.ArchivedAt,
		&i.ArchivedBy,
		&i.Key,
		&i.System,
		&i.PublishedVersionID,
		&i.ContractRequiredVariables,
		&i.OperatorRequiredVariables,
		&i.SeedRefusedAt,
		&i.SeedRefusedRules,
		&i.SeedRefusedPayloadSha256,
		&i.ContentSensitive,
		&i.SensitiveVariables,
		&i.Channel,
	)
	return i, err
}
